# -*- coding: utf-8 -*-
"""Просьба владельца 20.11: 5 экспрессов на сегодня, общий кэф 1,85–2,00, логика каждого события в посте.
Данные: КХЛ run 1452 (brief.md), футбол run 1463 (FD*). Кэфы Фонбета, кроме «Бавария — Кёльн» (Pinnacle)."""
import json
D = 'team/out/2026-11-20'
def L(lg, h, a, t, k, p, s, f, why):
    return dict(home=h, away=a, date='2026-11-20', time=t, league=lg, kef=k, p=p, bet_short=s, bet_full=f, why=why)
C = [
 [L('КХЛ', 'Торпедо', 'Локомотив', '19:00', 1.48, .693, 'ТМ 5,5', 'тотал матча меньше 5,5 в основное время',
    'Локомотив пропускает всего 1,56 за игру — одна из лучших оборон лиги. Меньше шести голов было в 17 матчах Торпедо из 26 и в 19 матчах Локомотива из 27. Обе команды из первой четвёрки, в таких матчах скорее душат, чем перестреливаются.'),
  L('КХЛ', 'Шанхайские Драконы', 'ЦСКА', '19:30', 1.30, .774, 'ТМ 6,5', 'тотал матча меньше 6,5 в основное время',
    'ЦСКА пропускает 1,78 за игру. В среднем в матчах ЦСКА 4,9 гола, у Шанхая 5,3. Чтобы ставка не зашла, нужно 7+ шайб за 60 минут: запас почти в две шайбы.')],
 [L('КХЛ', 'Северсталь', 'Амур', '19:00', 1.42, .708, 'Амур +1,5', 'фора Амура +1,5 в основное время',
    'Амур выиграл пять матчей подряд и пропускает 1,59 за игру. У него уже 8 сухих побед. В гостях 9 побед в 15 матчах. Проиграть Северстали две шайбы и больше такой обороне сложно.'),
  L('Футбол', 'Бавария', 'Кёльн', '22:30', 1.34, .844, 'ТБ 3,5', 'тотал матча больше 3,5',
    'Бавария забивает 3,2 за матч и бьёт по воротам 23 раза за игру. Больше двух голов было в 8 матчах Баварии из 9. Кёльн пропускает 1,6 за матч, в 7 из 9 его матчей забивали обе команды. В последних очных — 5:1 и 3:1.')],
 [L('КХЛ', 'Сибирь', 'Автомобилист', '15:30', 1.40, .703, 'Сибирь +1,5', 'фора Сибири +1,5 в основное время',
    'Автомобилист в гостях совсем другой, чем дома: 4 победы в 13 выездах, пропускает 3,15 за игру. Сибирь дома пропускает 2,4 за игру. Самый частый счёт в таком матче — равный, разгром хозяев на две шайбы маловероятен.'),
  L('Футбол', 'Труа', 'Гавр', '22:45', 1.33, .737, 'ТМ 3,5', 'тотал матча меньше 3,5',
    'Встречаются две из самых слабых атак Лиги 1: Труа забивает 0,7 за матч, Гавр — 0,9. Больше двух голов было лишь в 3 матчах Труа из 10. Четыре гола в этой паре — редкость.')],
 [L('КХЛ', 'Авангард', 'Барыс', '16:30', 1.30, .757, 'ТМ 6,5', 'тотал матча меньше 6,5 в основное время',
    'Авангард — одна из самых «сухих» команд: в среднем 4,2 гола в его матчах, меньше шести — в 19 из 26. Барыс любит результативный хоккей, но 7 шайб за основное время против такой обороны — это перебор.'),
  L('Футбол', 'Атлетик', 'Эспаньол', '23:00', 1.50, .686, 'П1', 'победа Атлетика',
    'Дома Атлетик набирает 1,83 очка за игру: последние домашние — 4:0 с Хетафе и 2:1 с Сосьедадом. Эспаньол забивает 1,1 за матч и бьёт в створ 3,4 раза за игру. Атлетик сильнее по всем линиям, особенно на своём поле.')],
 [L('КХЛ', 'Торпедо', 'Локомотив', '19:00', 1.33, .742, 'Торпедо +1,5', 'фора Торпедо +1,5 в основное время',
    'Торпедо — четвёртое место, дома пропускает 2,0 за игру и проиграло в основное время всего 7 матчей из 26. Локомотив выигрывает, но не громит: шайб у него 2,7 за игру. Проиграть дома две шайбы и больше Торпедо сложно.'),
  L('КХЛ', 'Северсталь', 'Амур', '19:00', 1.45, .665, 'ТМ 5,5', 'тотал матча меньше 5,5 в основное время',
    'В матчах Амура в среднем 3,6 гола за основное время; меньше шести было в 22 его матчах из 27. У Северстали — в 17 из 27. Амур играет от обороны, и шесть шайб за 60 минут против него набрать трудно.')],
]
def fmt(x): return ('%.2f' % x).replace('.', ',')
coupons, msgs = [], []
for i, legs in enumerate(C, 5):
    legs.sort(key=lambda l: l['time'])
    k = round(legs[0]['kef'] * legs[1]['kef'], 2)
    assert 1.85 <= k <= 2.0, k
    coupons.append(dict(size=2, legs=[{x: v for x, v in l.items() if x != 'why'} for l in legs], kef=k,
                        p=round(legs[0]['p'] * legs[1]['p'], 4)))
    lgs = {l['league'] for l in legs}
    head = 'КХЛ' if lgs == {'КХЛ'} else 'Хоккей и футбол'
    tags = '#кхл #экспресс #jarvibet' if head == 'КХЛ' else '#кхл #футбол #экспресс #jarvibet'
    t = ['%s · 20 ноября · экспресс' % head, '']
    for j, l in enumerate(legs, 1):
        t += ['%d. <b>%s — %s</b>, %s МСК' % (j, l['home'], l['away'], l['time']),
              '%s · %s' % (l['bet_full'], fmt(l['kef'])), '<i>Почему:</i> ' + l['why'], '']
    t += ['Общий кэф: <b>%s</b>' % fmt(k), '', tags]
    text = '\n'.join(t)
    assert len(text) <= 1024, (i, len(text))
    msgs.append({"to": "owner", "type": "animation", "html": True, "files": ["out/express/2026-11-20-logic/e%d_anim.mp4" % (i - 4)],
                 "text": text, "buttons": "post", "pid": "2011-e%d" % i})
    print(len(text), text, '\n----')
json.dump({'coupons': coupons}, open(D + '/express_logic_coupons.json', 'w'), ensure_ascii=False, indent=1)
intro = {"to": "owner", "type": "text", "text": "Экспрессы на сегодня по твоей просьбе — 5 вариантов, общий кэф 1,86–1,95, у каждого события разбор прямо в посте (2011-e5…e9). КХЛ с 15:30, футбол с 22:30; НХЛ на эту ночь в линии нет. Кэфы Фонбета на утро — сверь перед публикацией; на «Бавария — Кёльн» (тотал больше 3,5) кэф Pinnacle — у Фонбета проверь. Матчи повторяются не больше чем в двух вариантах, с утренними e1–e4 не совпадают."}
json.dump({"day": "2026-11-20", "make": ["team/picks/express_render.py %s/express_logic_coupons.json out/express/2026-11-20-logic" % D],
           "messages": [intro] + msgs}, open(D + '/express_logic.json', 'w'), ensure_ascii=False, indent=1)
